# owner: platform
import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundSpansTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        spans = [Span(9 * 60 + 2, 17 * 60 + 13)]
        self.assertEqual(
            round_spans(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_halves_round_up(self):
        spans = [Span(9 * 60 + 15, 10 * 60)]
        self.assertEqual(
            round_spans(spans, 30), ["09:30-10:00 (0h 30m)"]
        )

    def test_one_label_per_span(self):
        spans = [Span(60, 120), Span(180, 300)]
        self.assertEqual(
            round_spans(spans, 30),
            ["01:00-02:00 (1h 0m)", "03:00-05:00 (2h 0m)"]
        )

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 90):
            with self.assertRaises(ValueError):
                round_spans([Span(60, 120)], step)


if __name__ == "__main__":
    unittest.main()
